"""Render the three operator decisions in UTF-8, with the full 315-line audit."""
from pathlib import Path
import json,html
P=Path(__file__).resolve().parents[6]/'outputs/pysb-invoice-migration-20261013'
def main():
 data=json.loads((P/'invoice-bill-exception-decisions.json').read_text(encoding='utf8'))
 cases=[{'id':'EX-01','exception':'129 chứng từ / 315 dòng dùng tài khoản 6099.10000 hoặc 5050.00040 đã archived trên v19.','decision':'Dùng tài khoản đang cấu hình trên v19','result':'302 dòng có cấu hình được ánh xạ theo sản phẩm/nhóm; 13 dòng còn lại được chốt riêng theo EX-02/EX-03. Không mở lại hoặc tạo tài khoản.'},{'id':'EX-02','exception':'12 Invoice có SC-F130, CHILLER JY-B05 hoặc TENNETH F3550E chưa cấu hình tài khoản doanh thu.','decision':'Ánh xạ 5060/5070 như đề xuất','result':'SC-F130: 9 dòng → 5060.00000 (Sales Printing Machine). CHILLER/TENNETH: 3 dòng → 5070.00000 (Sales Finishing Machine). Cả 12 Invoice đã posted.'},{'id':'EX-03','exception':'SC-F9530 trên BILL/2026/07/0111 chưa cấu hình tài khoản mua hàng.','decision':'Dùng 6060.00000 rồi post','result':'1 dòng → 6060.00000 (Purchases Printing Machine). Bill đã posted.'}]
 decisions={c['id']:c['decision'] for c in cases};data['cases']=cases
 for r in data['rows']:r['decision']=decisions[r['exception']]
 assert len(data['rows'])==315 and len({r['source_id'] for r in data['rows']})==129 and all(r['state']=='posted' for r in data['rows'])
 note='EX-02 và EX-03 nằm trong EX-01; tổng vẫn là 129 chứng từ / 315 dòng. Chỉ sửa tài khoản trên dòng khi chứng từ còn nháp; giữ ngày, số tiền và liên kết SO/PO. Không sửa danh mục sản phẩm/tài khoản.'
 extra='Yêu cầu bổ sung của Bruce: “các invoice và bill cũng cần giữ được E-invoice reference từ v14”. Đã giữ và đối chiếu metadata 1.057/1.057 chứng từ; 834 có UUID/reference, 833 có LongId. Nguồn trống được giữ trống; không gửi lại e-invoice. Đây là yêu cầu bổ sung, không phải câu hỏi ngoại lệ.'
 outcome='Đã post đủ 960 Invoice + 97 Bill; không còn chứng từ thuộc phạm vi chờ post. Ngày và số tiền đối chiếu đạt. Payment, reconcile và bank statement để bước sau.'
 md='# Ngoại lệ và quyết định của Bruce — Post Invoice/Bill\n\n**14/10/2026 · Pao Yeang ID 1 · v19 staging `py19-staging-39654560`.**\n\nBáo cáo ba câu hỏi chốt ngoại lệ trong lượt post vừa thực hiện.\n\n| Mã | Ngoại lệ | Quyết định của Bruce | Kết quả |\n|---|---|---|---|\n'+''.join('| '+c['id']+' | '+c['exception']+' | **“'+c['decision']+'”** | '+c['result']+' |\n' for c in cases)+'\n'+note+'\n\n## Yêu cầu bổ sung\n\n'+extra+'\n\n## Kết quả cuối lượt\n\n'+outcome+'\n\n[Chi tiết 315 dòng thay tài khoản](PYSB_Invoice_Bill_Exception_Decisions.html) · [Báo cáo post và E-invoice](PYSB_Invoice_Bill_Posting_Review.html)\n'
 (P/'PYSB_Invoice_Bill_Exception_Decisions.md').write_text(md,encoding='utf8');(P/'invoice-bill-exception-decisions.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
 headers=['Mã','Chứng từ v14','ID v19','Dòng v14','Sản phẩm','Tài khoản cũ','Tài khoản mới','Quyết định Bruce','Trạng thái'];fields=['exception','source_document','target_document','source_line','product','old_account','new_account','decision','state'];table=''.join('<tr>'+''.join('<td>'+html.escape(str(r[k]))+'</td>' for k in fields)+'</tr>' for r in data['rows']);details=''.join('<h2>'+c['id']+'</h2><p>'+html.escape(c['exception'])+'</p><p><b>Bruce: “'+html.escape(c['decision'])+'”</b></p><p>'+html.escape(c['result'])+'</p>' for c in cases)
 page='<meta charset="utf-8"><title>PYSB — Ngoại lệ và quyết định Bruce</title><style>body{font:14px Arial;margin:24px}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:6px}th{background:#eef4fa}</style><h1>Ngoại lệ và quyết định của Bruce — Post Invoice/Bill</h1><p>14/10/2026 · Pao Yeang ID 1 · py19-staging-39654560.</p>'+details+'<p>'+html.escape(note)+'</p><p>'+html.escape(extra)+'</p><p>'+html.escape(outcome)+'</p><h2>Chi tiết 315 dòng</h2><table><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr>'+table+'</table>'
 (P/'PYSB_Invoice_Bill_Exception_Decisions.html').write_text(page,encoding='utf8');assert 'Quyết định' in md and 'Dùng 6060.00000 rồi post' in page;print(json.dumps({'decisions':3,'documents':129,'lines':315,'utf8_verified':True}))
if __name__=='__main__':main()
